-- Animal Racing Social: betting-side data model (PostgreSQL 16)
-- One Postgres instance on the VPS, one schema per owning service.
-- Rationale, sharding and Redis keys: docs/db/data-model.md
--
-- Conventions
--   ids     : BIGINT, generated by the app (64-bit: timestamp | logical shard | seq)
--   points  : BIGINT (whole points, no fractions)
--   prices  : NUMERIC(12,4) per leg; combined price NUMERIC(20,4)
--   time    : TIMESTAMPTZ (UTC)
--   [U] = user-scoped table, leading column user_id: moves to user shards later
--   [G] = global table, stays on the global database

CREATE SCHEMA identity;
CREATE SCHEMA stable;
CREATE SCHEMA racing;
CREATE SCHEMA sealed;        -- readable only by race-engine (write) and race-broadcaster (read)
CREATE SCHEMA market;
CREATE SCHEMA betting;
CREATE SCHEMA wallet;
CREATE SCHEMA season;
CREATE SCHEMA notification;
CREATE SCHEMA admin;

-- ───────────────────────────── identity ─────────────────────────────

CREATE TABLE identity.users (                                   -- [U]
  user_id       BIGINT PRIMARY KEY,
  display_name  TEXT NOT NULL,
  avatar_url    TEXT,
  role          TEXT NOT NULL DEFAULT 'USER' CHECK (role IN ('USER','ADMIN')),
  banned_at     TIMESTAMPTZ,
  ban_reason    TEXT,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE identity.user_identities (                        -- [G] login lookup → user_id
  provider          TEXT NOT NULL CHECK (provider IN ('google','github')),
  provider_subject  TEXT NOT NULL,
  user_id           BIGINT NOT NULL,
  email             TEXT,                -- informational only, never an identity key
  linked_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (provider, provider_subject)
);
CREATE INDEX ON identity.user_identities (user_id);

CREATE TABLE identity.refresh_tokens (                         -- [U]
  user_id     BIGINT NOT NULL,
  token_id    BIGINT NOT NULL,
  token_hash  BYTEA NOT NULL,
  family_id   BIGINT NOT NULL,           -- rotation family; reuse of a rotated token revokes the family
  expires_at  TIMESTAMPTZ NOT NULL,
  revoked_at  TIMESTAMPTZ,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, token_id)
);
CREATE UNIQUE INDEX ON identity.refresh_tokens (token_hash);

-- ───────────────────────────── stable ─────────────────────────────

CREATE TABLE stable.species (                                   -- [G]
  species            TEXT PRIMARY KEY,   -- HORSE | GIRAFFE
  max_career_days    INT  NOT NULL,      -- 140
  life_stages        JSONB NOT NULL,     -- {"ROOKIE":[0,25],"PRIME":[25,95],"VETERAN":[95,140]}
  age_curve          JSONB NOT NULL,     -- ageFactor control points per career day
  surface_affinity   JSONB NOT NULL,     -- {"DIRT":1.05,"MUD":0.9,...}
  segment_affinity   JSONB NOT NULL,     -- {"CURVE":1.0,"HAIRPIN":0.85,...}
  retire_threshold   NUMERIC(6,3) NOT NULL,
  target_pool_size   INT NOT NULL        -- ~60
);

CREATE TABLE stable.animals (                                   -- [G]
  animal_id        BIGINT PRIMARY KEY,
  species          TEXT NOT NULL REFERENCES stable.species,
  name             TEXT NOT NULL,
  temperament      TEXT NOT NULL CHECK (temperament IN ('FRONT_RUNNER','STALKER','CLOSER','STEADY')),
  status           TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','RETIRED')),
  recruited_at     TIMESTAMPTZ NOT NULL,
  career_day       INT NOT NULL,         -- 1 real day = 1 animal week; enters at random ROOKIE day
  age_weeks        INT NOT NULL,         -- display age
  life_stage       TEXT NOT NULL CHECK (life_stage IN ('ROOKIE','PRIME','VETERAN')),
  base_velocity    NUMERIC(6,3) NOT NULL,
  base_stamina     NUMERIC(6,3) NOT NULL,
  base_acceleration NUMERIC(6,3) NOT NULL,
  base_consistency NUMERIC(6,3) NOT NULL,
  cur_velocity     NUMERIC(6,3) NOT NULL,  -- base × ageFactor, refreshed daily
  cur_stamina      NUMERIC(6,3) NOT NULL,
  cur_acceleration NUMERIC(6,3) NOT NULL,
  cur_consistency  NUMERIC(6,3) NOT NULL,
  resting_until    TIMESTAMPTZ,          -- recovery after last race
  retired_at       TIMESTAMPTZ,
  retire_reason    TEXT CHECK (retire_reason IN ('AGE','DECLINE','ADMIN')),
  -- denormalized form (updated on RaceFinished)
  races            INT NOT NULL DEFAULT 0,
  wins             INT NOT NULL DEFAULT 0,
  podiums          INT NOT NULL DEFAULT 0,
  last5            TEXT[] NOT NULL DEFAULT '{}',   -- e.g. {'1','3','DQ','2','NR'}
  UNIQUE (species, name)
);
CREATE INDEX ON stable.animals (species, status, resting_until);

CREATE TABLE stable.animal_daily_stats (                        -- [G] aging history for charts
  animal_id   BIGINT NOT NULL REFERENCES stable.animals,
  day         DATE NOT NULL,
  career_day  INT NOT NULL,
  life_stage  TEXT NOT NULL,
  stats       JSONB NOT NULL,           -- current stats that day
  PRIMARY KEY (animal_id, day)
);

CREATE TABLE stable.animal_venue_form (                         -- [G] "course specialist"
  animal_id  BIGINT NOT NULL REFERENCES stable.animals,
  venue_id   TEXT NOT NULL,
  races      INT NOT NULL DEFAULT 0,
  wins       INT NOT NULL DEFAULT 0,
  podiums    INT NOT NULL DEFAULT 0,
  PRIMARY KEY (animal_id, venue_id)
);

-- ───────────────────────────── racing ─────────────────────────────

CREATE TABLE racing.venues (                                    -- [G] immutable versions
  venue_id     TEXT NOT NULL,
  version      INT  NOT NULL,
  name         TEXT NOT NULL,
  race_class   TEXT NOT NULL CHECK (race_class IN ('SPRINT','STANDARD','ENDURANCE')),
  surface      TEXT NOT NULL CHECK (surface IN ('DIRT','GRASS','SAND','MUD','ICE')),
  lanes        INT  NOT NULL DEFAULT 10,
  lap_length   NUMERIC(8,2) NOT NULL,
  laps_min     INT NOT NULL,
  laps_max     INT NOT NULL,
  segments     JSONB NOT NULL,
  assets       JSONB NOT NULL,
  status       TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('DRAFT','ACTIVE','RETIRED')),
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (venue_id, version)
);

CREATE TABLE racing.engine_versions (                           -- [G]
  engine_version  TEXT PRIMARY KEY,      -- semver of race-engine-core
  params          JSONB NOT NULL,        -- incident rates, noise, drain curves
  params_hash     BYTEA NOT NULL,
  is_active       BOOLEAN NOT NULL DEFAULT false,  -- exactly one active
  replayable      BOOLEAN NOT NULL DEFAULT true,   -- binary still deployed
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX ON racing.engine_versions (is_active) WHERE is_active;

CREATE TABLE racing.races (                                     -- [G]
  race_id              BIGINT PRIMARY KEY,
  season_id            BIGINT NOT NULL,
  species              TEXT NOT NULL,
  race_class           TEXT NOT NULL,
  venue_id             TEXT NOT NULL,
  venue_version        INT  NOT NULL,
  engine_version       TEXT NOT NULL REFERENCES racing.engine_versions,
  laps                 INT  NOT NULL,
  estimated_duration_s INT  NOT NULL,
  tick_ms              INT  NOT NULL DEFAULT 500,
  status               TEXT NOT NULL CHECK (status IN
                         ('SCHEDULED','OPEN','LOCKED','LIVE','FINISHED','SETTLED','CANCELLED')),
  start_at             TIMESTAMPTZ NOT NULL,
  betting_closes_at    TIMESTAMPTZ NOT NULL,   -- start_at − 60 s
  seed_hash            BYTEA,                  -- set on ScriptSealed
  script_hash          BYTEA,
  seed                 BYTEA,                  -- copied here only at FINISHED (public)
  finish_tick          INT,                    -- set at FINISHED
  started_at           TIMESTAMPTZ,
  finished_at          TIMESTAMPTZ,
  replay_expires_at    TIMESTAMPTZ,            -- finished_at + REPLAY_RETENTION_HOURS
  cancelled_reason     TEXT,
  created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
  FOREIGN KEY (venue_id, venue_version) REFERENCES racing.venues,
  CHECK (betting_closes_at = start_at - interval '60 seconds')
);
CREATE INDEX ON racing.races (status, start_at);
CREATE INDEX ON racing.races (start_at DESC);
CREATE INDEX ON racing.races (venue_id, start_at DESC);
CREATE INDEX ON racing.races (season_id);

CREATE TABLE racing.race_entrants (                             -- [G]
  race_id          BIGINT NOT NULL REFERENCES racing.races,
  entrant_id       INT    NOT NULL,          -- 1..10 within the race
  animal_id        BIGINT NOT NULL REFERENCES stable.animals,
  lane             INT    NOT NULL,
  temperament      TEXT   NOT NULL,
  stats_snapshot   JSONB  NOT NULL,          -- stats shown when betting opened
  -- result (set at FINISHED)
  official_position INT,
  as_run_position   INT,
  result_status     TEXT CHECK (result_status IN ('FINISHED','DISQUALIFIED','DNF','NON_RUNNER')),
  finish_time_ms    INT,                     -- interpolated crossing time; null for DNF/NR
  distance_covered  NUMERIC(10,2),
  PRIMARY KEY (race_id, entrant_id),
  UNIQUE (race_id, lane),
  UNIQUE (race_id, animal_id),
  UNIQUE (race_id, official_position)        -- no ties, ever
);
CREATE INDEX ON racing.race_entrants (animal_id, race_id DESC);   -- animal history

CREATE TABLE racing.race_lap_leaders (                          -- [G]
  race_id     BIGINT NOT NULL REFERENCES racing.races,
  lap         INT NOT NULL,
  entrant_id  INT NOT NULL,
  tick        INT NOT NULL,
  PRIMARY KEY (race_id, lap)
);

CREATE TABLE racing.race_incidents (                            -- [G]
  race_id     BIGINT NOT NULL REFERENCES racing.races,
  seq         INT NOT NULL,
  tick        INT NOT NULL,
  type        TEXT NOT NULL CHECK (type IN
                ('STUMBLE','FALSE_START','REFUSED_TO_RUN','PULLED_UP','DISQUALIFIED','PHOTO_FINISH')),
  entrant_id  INT,
  data        JSONB NOT NULL DEFAULT '{}',
  PRIMARY KEY (race_id, seq)
);

CREATE TABLE racing.programme (                                 -- [G] singleton-ish config, versioned
  version          INT PRIMARY KEY,
  races_per_hour   INT NOT NULL DEFAULT 3,
  class_mix        JSONB NOT NULL,     -- per-hour slot pattern
  species_rotation TEXT[] NOT NULL,    -- {'HORSE','GIRAFFE'}
  horizon_hours    INT NOT NULL DEFAULT 24,
  recovery_minutes JSONB NOT NULL,     -- {"SPRINT":60,"STANDARD":90,"ENDURANCE":120}
  effective_from   TIMESTAMPTZ NOT NULL,
  created_by       BIGINT NOT NULL
);

-- ───────────────────────────── sealed (scripts) ─────────────────────────────
-- Separate schema + DB role. No admin/API role has SELECT before FINISHED.

CREATE TABLE sealed.race_scripts (
  race_id         BIGINT PRIMARY KEY,
  key_id          TEXT  NOT NULL,          -- envelope-encryption key reference
  seed_ciphertext BYTEA NOT NULL,
  script_ciphertext BYTEA NOT NULL,        -- zstd(JSON script) encrypted
  script_bytes    INT   NOT NULL,
  sealed_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  revealed_at     TIMESTAMPTZ,             -- FINISHED: plaintext copied to racing.race_replays
  expires_at      TIMESTAMPTZ              -- deleted by retention job
);

CREATE TABLE racing.race_replays (                              -- [G] public after FINISHED
  race_id      BIGINT PRIMARY KEY REFERENCES racing.races,
  script       BYTEA NOT NULL,             -- zstd(JSON)
  expires_at   TIMESTAMPTZ NOT NULL        -- REPLAY_RETENTION_HOURS (≥ 24)
);

-- ───────────────────────────── market ─────────────────────────────

CREATE TABLE market.market_templates (                          -- [G] versioned per class
  race_class   TEXT NOT NULL,
  version      INT  NOT NULL,
  definition   JSONB NOT NULL,
  is_active    BOOLEAN NOT NULL DEFAULT false,
  created_by   BIGINT NOT NULL,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (race_class, version)
);
CREATE UNIQUE INDEX ON market.market_templates (race_class) WHERE is_active;

CREATE TABLE market.markets (                                   -- [G]
  market_id        BIGINT PRIMARY KEY,
  race_id          BIGINT NOT NULL REFERENCES racing.races,
  type             TEXT NOT NULL CHECK (type IN ('FINISH_POSITION','TOP_N','TRICAST','LEADER_AT_LAP')),
  params           JSONB NOT NULL DEFAULT '{}',   -- {"position":2} | {"n":3} | {"lap":5}
  status           TEXT NOT NULL CHECK (status IN ('PENDING','OPEN','SUSPENDED','CLOSED','RESULTED','VOID')),
  template_version INT NOT NULL,
  opens_rule       JSONB NOT NULL,
  closes_rule      JSONB NOT NULL,
  price_version    INT NOT NULL DEFAULT 0,
  opened_at        TIMESTAMPTZ,
  closed_at        TIMESTAMPTZ,
  resulted_at      TIMESTAMPTZ,
  result           JSONB,                -- {"winning":[selectionId]} | {"order":[e1,e2,e3]}
  UNIQUE (race_id, type, params)
);
CREATE INDEX ON market.markets (race_id, status);

CREATE TABLE market.selections (                                -- [G] latest price only
  selection_id   BIGINT PRIMARY KEY,
  market_id      BIGINT NOT NULL REFERENCES market.markets,
  race_id        BIGINT NOT NULL,
  entrant_id     INT    NOT NULL,
  price          NUMERIC(12,4) NOT NULL,
  probability    NUMERIC(8,6)  NOT NULL,
  price_version  INT NOT NULL,
  UNIQUE (market_id, entrant_id)
);
-- Price history is not stored per tick in Postgres (Kafka `market.events` is the log).
-- Pre-race and race-start prices are kept for history/analytics:
CREATE TABLE market.price_snapshots (                           -- [G]
  market_id   BIGINT NOT NULL REFERENCES market.markets,
  kind        TEXT NOT NULL CHECK (kind IN ('OPENING','AT_LOCK','AT_START')),
  prices      JSONB NOT NULL,            -- {entrantId: price}
  taken_at    TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (market_id, kind)
);

-- Full per-second price history, written once when a market results.
-- One compressed columnar series per market (~600 rows/day). Purged after
-- PRICE_HISTORY_RETENTION (config, default = one season length, 28 days rolling).
CREATE TABLE market.price_history (                             -- [G]
  market_id   BIGINT PRIMARY KEY REFERENCES market.markets,
  race_id     BIGINT NOT NULL,
  first_tick  INT NOT NULL,
  step_ticks  INT NOT NULL DEFAULT 2,       -- one point per reprice (1 s)
  points      INT NOT NULL,
  series      BYTEA NOT NULL,               -- zstd(columnar: tick[], per-entrant price[])
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at  TIMESTAMPTZ NOT NULL           -- created_at + PRICE_HISTORY_RETENTION
);
CREATE INDEX ON market.price_history (race_id);
CREATE INDEX ON market.price_history (expires_at);

-- ───────────────────────────── betting ─────────────────────────────

CREATE TABLE betting.bets (                                     -- [U]
  user_id              BIGINT NOT NULL,
  bet_id               BIGINT NOT NULL,
  season_id            BIGINT NOT NULL,
  type                 TEXT NOT NULL CHECK (type IN ('SINGLE','COMBO')),
  status               TEXT NOT NULL CHECK (status IN
                         ('PENDING','ACCEPTED','REJECTED','WON','LOST','VOID','CASHED_OUT')),
  stake                BIGINT NOT NULL CHECK (stake >= 1),
  leg_count            SMALLINT NOT NULL CHECK (leg_count BETWEEN 1 AND 8),
  accept_price_changes TEXT NOT NULL DEFAULT 'NONE' CHECK (accept_price_changes IN ('NONE','BETTER','ANY')),
  locked_price         NUMERIC(20,4),      -- Π leg prices (void legs = 1.0)
  payout               BIGINT,
  cashout_amount       BIGINT,
  reject_reason        TEXT,
  idempotency_key      UUID NOT NULL,
  requested_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  accepted_at          TIMESTAMPTZ,
  settled_at           TIMESTAMPTZ,
  PRIMARY KEY (user_id, bet_id),
  UNIQUE (user_id, idempotency_key),
  CHECK ((type = 'SINGLE') = (leg_count = 1))
);
CREATE INDEX ON betting.bets (user_id, requested_at DESC);
CREATE INDEX ON betting.bets (user_id, status) WHERE status IN ('PENDING','ACCEPTED');

CREATE TABLE betting.bet_legs (                                 -- [U]
  user_id          BIGINT NOT NULL,
  bet_id           BIGINT NOT NULL,
  leg_no           SMALLINT NOT NULL,
  market_id        BIGINT NOT NULL,
  race_id          BIGINT NOT NULL,
  entrant_id       INT,                    -- single-entrant selections
  tricast_order    INT[],                  -- TRICAST: {1st,2nd,3rd}
  accepted_price   NUMERIC(12,4) NOT NULL, -- what the client saw
  price_version    INT NOT NULL,
  locked_price     NUMERIC(12,4),          -- price at acceptance
  status           TEXT NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','WON','LOST','VOID')),
  placed_at_tick   INT,                    -- null if placed pre-race
  settled_at       TIMESTAMPTZ,
  PRIMARY KEY (user_id, bet_id, leg_no),
  FOREIGN KEY (user_id, bet_id) REFERENCES betting.bets,
  UNIQUE (user_id, bet_id, race_id),       -- combo: one leg per race
  CHECK ((entrant_id IS NULL) <> (tricast_order IS NULL))
);
-- Settlement: "all open legs on market X" (per shard)
CREATE INDEX ON betting.bet_legs (market_id) WHERE status = 'OPEN';
CREATE INDEX ON betting.bet_legs (race_id, user_id);   -- "my bets on this race" (SSE snapshot, RACE_STARTING)

CREATE TABLE betting.cashouts (                                 -- [U]
  user_id          BIGINT NOT NULL,
  bet_id           BIGINT NOT NULL,
  cashout_id       BIGINT NOT NULL,
  quote_id         TEXT   NOT NULL,
  quoted_amount    BIGINT NOT NULL,
  min_amount       BIGINT NOT NULL,
  final_amount     BIGINT,
  status           TEXT NOT NULL CHECK (status IN ('PENDING','ACCEPTED','REJECTED')),
  reject_reason    TEXT,
  idempotency_key  UUID NOT NULL,
  requested_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  decided_at       TIMESTAMPTZ,
  PRIMARY KEY (user_id, cashout_id),
  FOREIGN KEY (user_id, bet_id) REFERENCES betting.bets,
  UNIQUE (user_id, idempotency_key)
);
-- at most one accepted cash-out per bet (full cash-out only)
CREATE UNIQUE INDEX ON betting.cashouts (user_id, bet_id) WHERE status = 'ACCEPTED';

-- ───────────────────────────── wallet ─────────────────────────────

CREATE TABLE wallet.wallets (                                   -- [U] one per user per season
  user_id      BIGINT NOT NULL,
  season_id    BIGINT NOT NULL,
  balance      BIGINT NOT NULL CHECK (balance >= 0),
  open_stake   BIGINT NOT NULL DEFAULT 0 CHECK (open_stake >= 0),  -- stakes in unsettled bets
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, season_id)
);
-- rankScore = balance + open_stake (open bets ignored by leaderboards)

CREATE TABLE wallet.ledger_entries (                            -- [U] append-only
  user_id        BIGINT NOT NULL,
  entry_id       BIGINT NOT NULL,
  season_id      BIGINT NOT NULL,
  type           TEXT NOT NULL CHECK (type IN
                   ('SEASON_GRANT','DAILY_GRANT','BET_STAKE','BET_PAYOUT','BET_REFUND','CASHOUT','ADMIN_ADJUST')),
  amount         BIGINT NOT NULL,          -- signed
  ref_id         TEXT   NOT NULL,          -- betId | "userId:YYYY-MM-DD" | seasonId | adminActionId
  balance_after  BIGINT NOT NULL,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, entry_id),
  UNIQUE (user_id, type, ref_id)           -- idempotent consumers
);
CREATE INDEX ON wallet.ledger_entries (user_id, season_id, created_at DESC);

CREATE TABLE wallet.daily_rewards (                             -- [U]
  user_id         BIGINT PRIMARY KEY,
  last_claim_day  DATE,
  streak          INT NOT NULL DEFAULT 0,
  best_streak     INT NOT NULL DEFAULT 0
);

-- ───────────────────────────── season & leaderboards ─────────────────────────────

CREATE TABLE season.seasons (                                   -- [G]
  season_id       BIGINT PRIMARY KEY,
  name            TEXT NOT NULL,
  status          TEXT NOT NULL CHECK (status IN ('UPCOMING','ACTIVE','ENDED')),
  starts_at       TIMESTAMPTZ NOT NULL,
  ends_at         TIMESTAMPTZ NOT NULL,
  last_race_at    TIMESTAMPTZ NOT NULL,         -- ends_at − 1 h (last race start)
  starting_grant  BIGINT NOT NULL DEFAULT 10000,
  daily_grant     BIGINT NOT NULL DEFAULT 50,
  CHECK (ends_at > starts_at),
  CHECK (last_race_at = ends_at - interval '1 hour'),
  EXCLUDE USING gist (tstzrange(starts_at, ends_at) WITH &&)
);

CREATE TABLE season.user_season_stats (                         -- [U] source for Redis boards
  user_id         BIGINT NOT NULL,
  season_id       BIGINT NOT NULL,
  settled_bets    INT    NOT NULL DEFAULT 0,
  total_staked    BIGINT NOT NULL DEFAULT 0,   -- settled bets only
  total_returned  BIGINT NOT NULL DEFAULT 0,   -- payouts + cash-outs + refunds
  biggest_payout  BIGINT NOT NULL DEFAULT 0,
  biggest_payout_bet BIGINT,
  current_streak  INT    NOT NULL DEFAULT 0,
  best_streak     INT    NOT NULL DEFAULT 0,
  rank_score      BIGINT NOT NULL DEFAULT 0,   -- balance + open_stake
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, season_id)
);
-- ROI = (total_returned − total_staked) / total_staked, ranked only if settled_bets ≥ 20

CREATE TABLE season.season_results (                            -- [G] frozen at SeasonEnded
  season_id   BIGINT NOT NULL REFERENCES season.seasons,
  board       TEXT   NOT NULL CHECK (board IN ('balance','biggest-payout','roi','win-streak')),
  rank        INT    NOT NULL,
  user_id     BIGINT NOT NULL,
  score       NUMERIC(20,4) NOT NULL,
  PRIMARY KEY (season_id, board, rank)
);
CREATE INDEX ON season.season_results (user_id);

-- ───────────────────────────── notification ─────────────────────────────

CREATE TABLE notification.notifications (                       -- [U] 30-day retention
  user_id          BIGINT NOT NULL,
  notification_id  BIGINT NOT NULL,
  type             TEXT NOT NULL CHECK (type IN
                     ('RACE_STARTING','BET_WON','BET_LOST','BET_VOID','BET_REJECTED',
                      'CASHOUT_DONE','CASHOUT_REJECTED','DAILY_REWARD_READY',
                      'LEADERBOARD_MOVE','SEASON_ENDING','SEASON_RESULT')),
  dedupe_key       TEXT NOT NULL,          -- e.g. "BET_WON:betId", "RACE_STARTING:raceId"
  payload          JSONB NOT NULL,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  read_at          TIMESTAMPTZ,
  PRIMARY KEY (user_id, notification_id),
  UNIQUE (user_id, dedupe_key)
);
CREATE INDEX ON notification.notifications (user_id, created_at DESC);
CREATE INDEX ON notification.notifications (user_id) WHERE read_at IS NULL;
-- Retention: daily job deletes created_at < now() − 30 days (or monthly partitions + DROP).

CREATE TABLE notification.settings (                            -- [U]
  user_id     BIGINT PRIMARY KEY,
  enabled     BOOLEAN NOT NULL DEFAULT true,
  types       JSONB   NOT NULL DEFAULT '{}',   -- {"RACE_STARTING":false}; missing = on
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ───────────────────────────── admin ─────────────────────────────

CREATE TABLE admin.audit_log (                                  -- [G] append-only
  audit_id       BIGINT PRIMARY KEY,
  admin_user_id  BIGINT NOT NULL,
  action         TEXT NOT NULL,            -- "race.cancel", "venue.publish", ...
  target_type    TEXT NOT NULL,
  target_id      TEXT NOT NULL,
  before         JSONB,
  after          JSONB,
  reason         TEXT,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX ON admin.audit_log (target_type, target_id, created_at DESC);

-- ───────────────────────────── infrastructure (per service schema) ─────────────────────────────
-- Each service that publishes events has its own outbox in its own schema.
-- Shown once; replicate as <schema>.outbox.

CREATE TABLE betting.outbox (
  outbox_id     BIGSERIAL PRIMARY KEY,
  topic         TEXT  NOT NULL,
  msg_key       TEXT  NOT NULL,
  event_type    TEXT  NOT NULL,
  payload       BYTEA NOT NULL,            -- protobuf
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  published_at  TIMESTAMPTZ
);
CREATE INDEX ON betting.outbox (outbox_id) WHERE published_at IS NULL;

CREATE TABLE betting.processed_events (                         -- consumer dedupe on eventId
  consumer      TEXT NOT NULL,
  event_id      UUID NOT NULL,
  processed_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (consumer, event_id)
);
